# Generated by manage.py generate_test_cases.
from types import SimpleNamespace
from typing import cast

from django import forms
from pydantic import ValidationError

from bloomerp.dataviews.definition import BaseDataviewRenderer, DataviewState
from bloomerp.dataviews.kanban.config import KanbanDataView
from bloomerp.dataviews.kanban.renderer import KanbanDataviewRenderer
from bloomerp.tests.base import BloomerpDataviewTestCase


class TestKanbanDataview(BloomerpDataviewTestCase):
    dataview_key = "kanban"

    def test_operations_declare_when_they_need_row_totals(self) -> None:
        """
        Use case: The generic operation endpoint asks renderers whether to count rows.
        Expected result: Existing renderers retain totals and Kanban saves opt out.
        """
        # 1. Preserve counting for renderers without an explicit override.
        self.assertTrue(BaseDataviewRenderer.action_requires_count("move"))
        # 2. Skip the unused board total only for a Kanban card save.
        self.assertFalse(KanbanDataviewRenderer.action_requires_count("move"))
        # 3. Keep totals available for lane loading and other operations.
        self.assertTrue(KanbanDataviewRenderer.action_requires_count("column"))
        self.assertTrue(KanbanDataviewRenderer.action_requires_count("unknown"))

    def test_rejects_ambiguous_groups_and_unsafe_colours(self) -> None:
        """
        Use case: Developers configure overlapping destinations or invalid CSS colours.
        Expected result: Configuration validation rejects ambiguous and unsafe inputs.
        """
        # 1. Reject values assigned to more than one custom lane.
        with self.assertRaises(ValidationError):
            KanbanDataView(
                custom_groupings={"First": ["applied"], "Second": ["applied"]}
            )
        # 2. Reject empty groups and unnamed lanes.
        for grouping in [{"First": []}, {" ": ["applied"]}]:
            with self.assertRaises(ValidationError):
                KanbanDataView(custom_groupings=grouping)
        # 3. Reject CSS expressions instead of six-digit hex colours.
        with self.assertRaises(ValidationError):
            KanbanDataView(lane_colouring={"applied": "red; background: url(example)"})

    def test_unmapped_lanes_option_defaults_and_checkbox(self) -> None:
        """
        Use case: Existing boards load or users disable unmapped lanes in options.
        Expected result: The default is true and an unchecked checkbox persists false.
        """
        # 1. Restore legacy options without changing their visible lanes.
        self.assertTrue(KanbanDataView.model_validate({}).show_unmapped_lanes)
        # 2. Validate the display option as an optional checkbox.
        field = KanbanDataView.create_form_field(
            "show_unmapped_lanes",
            KanbanDataView.model_fields["show_unmapped_lanes"],
            cast(DataviewState, SimpleNamespace(accessible_fields=[])),
        )
        self.assertIsInstance(field, forms.BooleanField)
        self.assertFalse(field.required)
        self.assertTrue(field.clean("on"))
        options = KanbanDataView(show_unmapped_lanes=field.clean(None))
        # 3. Preserve the explicit false value through saved options.
        self.assertFalse(
            KanbanDataView.model_validate(options.dump_options()).show_unmapped_lanes
        )
